<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Customer; use Illuminate\Http\Request;
class CustomerController extends Controller {public function index(Request $request){$customers=Customer::withCount('shipments')->when($request->filled('search'),function($q)use($request){$s=trim($request->input('search'));$q->where(fn($q)=>$q->where('name','like',"%$s%")->orWhere('email','like',"%$s%")->orWhere('phone','like',"%$s%"));})->latest()->paginate(20)->withQueryString();return view('admin.customers.index',compact('customers'));}public function create(){return view('admin.customers.create');}public function store(Request $request){$v=$request->validate(['name'=>['required','string','max:255'],'email'=>['nullable','email','max:255'],'phone'=>['nullable','string','max:50'],'address'=>['nullable','string','max:1000'],'notifications_enabled'=>['sometimes','boolean']]);$v['notifications_enabled']=$request->boolean('notifications_enabled');Customer::create($v);return redirect()->route('admin.customers.index')->with('success','Customer created successfully.');}public function edit(Customer $customer){return view('admin.customers.edit',compact('customer'));}public function update(Request $request,Customer $customer){$v=$request->validate(['name'=>['required','string','max:255'],'email'=>['nullable','email','max:255'],'phone'=>['nullable','string','max:50'],'address'=>['nullable','string','max:1000'],'notifications_enabled'=>['sometimes','boolean']]);$v['notifications_enabled']=$request->boolean('notifications_enabled');$customer->update($v);return redirect()->route('admin.customers.index')->with('success','Customer updated successfully.');}public function destroy(Customer $customer){if($customer->shipments()->exists())return back()->with('error','This customer cannot be deleted because they have shipments.');$customer->delete();return redirect()->route('admin.customers.index')->with('success','Customer deleted successfully.');}}
